import pandas as pd
import numpy as np

# Load data
df = pd.read_csv('chunks_csv/moran_local_2021_ghg.csv')
adj_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Calculate median GHG value for high/low classification
median_ghg = df['GHG_value'].median()
print(f"Median GHG value: {median_ghg}")

# Function to classify borough and neighbors
def classify_spot(borough_name):
    borough_ghg = df[df['borough'] == borough_name]['GHG_value'].values[0]
    neighbors = adj_df[adj_df['borough'] == borough_name]['neighbor'].tolist()

    if not neighbors:
        return None  # No neighbors to compare

    neighbor_ghgs = []
    for neighbor in neighbors:
        neighbor_ghg = df[df['borough'] == neighbor]['GHG_value'].values
        if len(neighbor_ghg) > 0:
            neighbor_ghgs.append(neighbor_ghg[0])

    if not neighbor_ghgs:
        return None  # No valid neighbor data

    neighbor_median = np.median(neighbor_ghgs)

    # Classify as HH or LL
    if borough_ghg > median_ghg and neighbor_median > median_ghg:
        return ('HH', borough_ghg, neighbor_median)
    elif borough_ghg < median_ghg and neighbor_median < median_ghg:
        return ('LL', borough_ghg, neighbor_median)
    else:
        return None

# Test all boroughs
results = []
for borough in df['borough']:
    classification = classify_spot(borough)
    if classification:
        results.append((borough, classification[0], classification[1], classification[2]))

# Print results
print("\nPotential hot/cold spots:")
for res in results:
    print(f"{res[0]}: {res[1]} (borough GHG={res[2]:.4f}, neighbor median GHG={res[3]:.4f})")

# Prepare final answer
final_answer = []
for res in results:
    final_answer.append(f"{res[0]} ({res[1]}, statistical method={res[2]:.4f})")

if final_answer:
    print("\nFINAL ANSWER: " + ", ".join(final_answer))
else:
    print("\nFINAL ANSWER: none")
